package com.biocircular.compostaje.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="movimiento_inventario_compost") public class MovimientoInventario { @Id @GeneratedValue private UUID id; @ManyToOne @JoinColumn(name="compost_id") private Compost compost; @Enumerated(EnumType.STRING) private TipoMovimiento tipo; @Column(name="cantidad_kg") private BigDecimal cantidadKg; @Column(name="fecha_hora") private OffsetDateTime fechaHora=OffsetDateTime.now(); private String motivo; @Column(name="usuario_externo_id") private UUID usuarioId; public UUID getId(){return id;} public Compost getCompost(){return compost;} public TipoMovimiento getTipo(){return tipo;} public BigDecimal getCantidadKg(){return cantidadKg;} public OffsetDateTime getFechaHora(){return fechaHora;} public String getMotivo(){return motivo;} public void crear(Compost c,TipoMovimiento t,BigDecimal x,String m,UUID u){compost=c;tipo=t;cantidadKg=x;motivo=m;usuarioId=u;} }
